/** @file
 * @brief cluster group prologue
 *
 * Generated by scripts/gen-suite.py: run "nosql-servers.sh cluster-up"
 * on the agent (the clusters live only while their group runs).
 */

#define TE_TEST_NAME    "cluster/prologue"

#include "te_config.h"
#include "tapi_test.h"

#include "tsapi_nosql.h"

int
main(int argc, char **argv)
{
    tsapi_nosql_sess sess = { 0 };

    TEST_START;
    TEST_STEP("nosql-servers.sh cluster-up");
    CHECK_RC(tsapi_nosql_sess_init(&sess, "pco_cluster_prologue"));
    rc = tsapi_nosql_servers(sess.pco, "cluster-up", NULL);
    if (rc != 0)
        TEST_VERDICT("nosql-servers.sh cluster-up failed");
    TEST_SUCCESS;
cleanup:
    tsapi_nosql_sess_fini(&sess);
    TEST_END;
}
